/**
 * spatial-factory: the state contract (what `$.state` holds for this session)
 * and the plain data types the hooks module and its tests share.
 *
 * Self-contained on purpose (no imports): `claude plugin validate` reads it as
 * the mod's contract, and `declare module 'claude-code'` below merges the
 * `spatial-factory` key into PluginState.
 */

/** One of the nine stages of FACTORY_PLAN §3, extended with 0 构思 / 1 PRD / 8 分发. */
export type FactoryStage = 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8;

/** Where the app stands. `waiting` = a human gate is open (see FactoryGate). */
export type FactoryStatus = 'pending' | 'running' | 'waiting' | 'blocked' | 'done';

/** The four human gates; each is `manual` (a press on the pane / `/factory approve`) or `auto` (passes by itself). */
export type FactoryGate = 'concept' | 'design' | 'iteration' | 'delivery';

export type FactoryGateMode = 'manual' | 'auto';

/** The `design` lane never touches the emulator or Gradle; the `emulator` lane does (one at a time per machine). */
export type FactoryLane = 'design' | 'emulator';

export type FactoryTokens = {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
};

/** One app bound to this session (one session = one app) and registered in `$.store` for every session to see. */
export type FactoryApp = {
  /** English name = project folder name, e.g. `GridSpace`. */
  app: string;
  titleZh: string;
  package: string;
  /** Absolute path of the brief.yaml this app was started from. */
  brief: string;
  /** Absolute path of the project folder (`<appsRoot>/<app>`). */
  projectDir: string;
  /** `spatial` (PICO Spatial SDK, the only stack this factory runs), else parked. */
  stack: 'spatial' | 'webspatial' | 'unity' | 'unknown';
  status: FactoryStatus;
  stage: FactoryStage;
  /** Round number, continuing across the app's life (R1…). */
  round: number;
  startedAt: number;
  updatedAt: number;
  tokens: FactoryTokens;
  gates: Record<FactoryGate, FactoryGateMode>;
  /** The gate that is open while `status === 'waiting'`. */
  waitingFor?: FactoryGate;
  /** Why it is blocked, or the last note. */
  note?: string;
  /** The session that owns it (one session = one app). */
  sessionId?: string;
  /** Budget from the brief: tokens (all four counts summed), hours, rounds. */
  budget: { tokens: number; hours: number; rounds: number };
};

export type GateResult = 'PASS' | 'FAIL' | 'WARN' | 'SKIP';

/** One column of the pane's gate table. */
export type GateCheck = {
  id: 'build' | 'tests' | 'dex' | 'strings' | 'px' | 'occlusion' | 'logs' | 'data';
  label: string;
  result: GateResult;
  /** One line of evidence (a count, a file, a FAIL line). */
  detail: string;
};

export type GateReport = {
  app: string;
  round: number;
  at: number;
  checks: GateCheck[];
  /** Every raw PASS/FAIL/WARN line the scripts printed, for the pane's detail view. */
  lines: string[];
};

/** An `adb shell settings put global <name>` the guard saw and nobody deleted yet. */
export type FactoryCleanup = {
  setting: string;
  at: number;
};

export type FactoryGuard = {
  /** The Bash call holding the one Gradle allowed at a time, or null. */
  gradle: { toolUseId: string; startedAt: number; command: string } | null;
  cleanup: FactoryCleanup[];
};

/** A line of the pane's event log (newest last). */
export type FactoryEvent = {
  at: number;
  text: string;
};

export type FactoryState = {
  current: FactoryApp | null;
  gate: GateReport | null;
  guard: FactoryGuard;
  events: FactoryEvent[];
  /** Absolute path of the newest montage JPEG, when one exists. */
  montage: string | null;
  /** A small JPEG thumbnail of the montage as a data URI, when it fits an Svg (≤ 90 KB). */
  montageThumb: string | null;
};

declare module 'claude-code' {
  interface PluginState {
    'spatial-factory': {
      current: FactoryApp | null;
      gate: GateReport | null;
      guard: FactoryGuard;
      events: FactoryEvent[];
      montage: string | null;
      montageThumb: string | null;
    };
  }
}

