140	   140	/** Runs a child to its end through `$.process.spawn`, streaming each piece to `onText`. */
141	   141	export async function runScript(
142	   142	  $: EngineInterface,
143	   143	  argv: readonly string[],
144	   144	  cwd: string,
145	   145	  onText?: (text: string) => void,
146	   146	): Promise<ScriptResult> {
147	   147	  const stream = $.process.spawn({ argv, cwd })
148	   148	  let text = ''
149	   149	  let step = await stream.next()
150	   150	  while (!step.done) {
151	   151	    text += step.value.text
152	   152	    onText?.(step.value.text)
153	   153	    step = await stream.next()
154	   154	  }
155	   155	  return { code: step.value.code, text }
156	   156	}
