263	   263	  const steps = (brief?.demo ?? [])
264	   264	    .map(d => (typeof d === 'object' && d !== null && !Array.isArray(d) ? String(d.step ?? '') : ''))
265	   265	    .filter(s => s !== '')
266	   266	  const langs = brief?.languages ?? ['zh', 'en']
267	   267	  for (const lang of langs) {
268	   268	    const out = `docs/screenshots/${prefix}/${lang}`
