274	   274	  let measureText: string | undefined
275	   275	  if (await exists($, `${P}/docs/scripts/measure.json`)) {
276	   276	    const outJson = `docs/gate/${prefix}-measure.json`
277	   277	    const r = await runScript($, ['python', '-P', 'docs/scripts/measure.py', `docs/screenshots/${prefix}`, prefix, 'docs/scripts/measure.json', '--langs', langs.join(','), '--json', outJson], P)
