281	   281	  let dataText: string | undefined
282	   282	  if (await exists($, `${P}/docs/scripts/data.sh`)) {
283	   283	    const r = await bash('docs/scripts/data.sh', [prefix])
284	   284	    dataText = r.text
285	   285	    await $.fs.write(`${gateDir}/${prefix}-data.txt`, r.text)
286	   286	  }
