309	   309	/** Runs the app's current stage once; the caller applies `afterStage`. */
310	   310	export async function runStage($: EngineInterface, app0: FactoryApp, ctx: RunContext): Promise<StageOutcome> {
311	   311	  let app = app0
312	   312	  const { deps } = ctx
313	   313	  switch (app.stage) {
314	   314	    case 0: {
315	   315	      await $.fs.write(`${app.projectDir}/docs/.factory`, `${app.app}\n`)
316	   316	      app = addUsage(app, await spawnStage($, app, 'concept', ctx))
317	   317	      break
318	   318	    }
319	   319	    case 1: {
320	   320	      app = addUsage(app, await spawnStage($, app, 'prd', ctx))
321	   321	      const text = await readOr($, app.brief)
322	   322	      const parsed = text ? parseBrief(text) : { brief: null, errors: ['brief 不可读'] }
323	   323	      if (parsed.brief) {
324	   324	        const fresh = appFromBrief(parsed.brief, app.brief, deps.appsRoot, app.startedAt, app.sessionId)
325	   325	        app = { ...app, titleZh: fresh.titleZh, package: fresh.package, gates: fresh.gates, budget: fresh.budget }
326	   326	      } else {
327	   327	        await ctx.log(`brief 仍有问题: ${parsed.errors.join('; ')}`)
328	   328	      }
329	   329	      break
330	   330	    }
331	   331	    case 2: {
332	   332	      app = addUsage(app, await spawnStage($, app, 'design', ctx))
333	   333	      break
334	   334	    }
335	   335	    case 3: {
336	   336	      const r = await runScript($, ['bash', `${deps.pluginRoot}/scripts/normalize.sh`, deps.factoryRoot, app.projectDir, deps.refProject, app.app, app.titleZh, app.package], app.projectDir, t => void ctx.log(t.trim()).catch(() => undefined))
337	   337	      if (r.code !== 0) throw new Error(`normalize.sh exit ${r.code}`)
338	   338	      const pre = await runScript($, ['bash', `${deps.factoryRoot}/skills/pico-spatial-machine-env/scripts/preflight.sh`, app.package], app.projectDir)
339	   339	      await $.fs.write(`${app.projectDir}/docs/gate/preflight.txt`, pre.text)
340	   340	      if (pre.code !== 0) throw new Error(`preflight FAIL:\n${pre.text.split('\n').filter(l => l.startsWith('FAIL')).join('\n')}`)
341	   341	      app = { ...app, round: Math.max(1, app.round) }
342	   342	      break
343	   343	    }
344	   344	    case 4: {
345	   345	      app = { ...app, round: Math.max(1, app.round) }
346	   346	      app = addUsage(app, await spawnStage($, app, 'eng', ctx))
347	   347	      break
348	   348	    }
349	   349	    case 5: {
350	   350	      const gate = await verify($, app, ctx)
351	   351	      return { app, gate }
352	   352	    }
353	   353	    case 6: {
354	   354	      app = addUsage(app, await spawnStage($, app, 'qa', ctx))
355	   355	      const report = (await readOr($, `${app.projectDir}/docs/QA_REPORT_R${Math.max(1, app.round)}.md`)) ?? ''
356	   356	      return { app, qaVerdict: qaVerdictFromReport(report) }
357	   357	    }
358	   358	    case 7: {
359	   359	      app = addUsage(app, await spawnStage($, app, 'fix', ctx))
360	   360	      break
361	   361	    }
362	   362	    case 8: {
363	   363	      app = addUsage(app, await spawnStage($, app, 'distribute', ctx))
364	   364	      break
365	   365	    }
366	   366	    default:
367	   367	      break
368	   368	  }
369	   369	  const missing = await requireOutputs($, app)
370	   370	  if (missing.length > 0) throw new Error(`阶段 ${app.stage} 未产出: ${missing.join(', ')}`)
371	   371	  return { app }
372	   372	}
