396	   396	/**
397	   397	 * Drives the app from its current stage until it waits at a human gate, is
398	   398	 * blocked, or is done. Each stage is one `runStage`; `afterStage` decides the
399	   399	 * next; the budget is checked before every stage (P5: fixed rounds, FACTORY_PLAN §3).
400	   400	 */
401	   401	export async function runLoop($: EngineInterface, start: FactoryApp, ctx: RunContext, ev: LoopEvents): Promise<FactoryApp> {
402	   402	  let app = start
403	   403	  if (app.stack !== 'spatial') {
404	   404	    app = { ...app, status: 'blocked', note: `技术栈 ${app.stack} 不在本工厂范围 (只跑 Spatial SDK)`, updatedAt: Date.now() }
405	   405	    await ev.save(app)
406	   406	    return app
407	   407	  }
408	   408	  while (app.status === 'pending') {
409	   409	    const over = overBudget(app, Date.now())
410	   410	    if (over) {
411	   411	      app = { ...app, status: 'blocked', note: over, updatedAt: Date.now() }
412	   412	      await writeBlocked($, app, over)
413	   413	      await ev.save(app)
414	   414	      ev.toast(`${app.app} 阻塞: ${over}`)
415	   415	      return app
416	   416	    }
417	   417	    app = { ...app, status: 'running', updatedAt: Date.now() }
418	   418	    await ev.save(app)
419	   419	    const info = stageInfo(app.stage)
420	   420	    await ev.log(`▶ 阶段 ${app.stage} ${info.zh} (R${Math.max(1, app.round)})`)
421	   421	    try {
422	   422	      const out = await runStage($, app, ctx)
423	   423	      app = { ...out.app, updatedAt: Date.now() }
424	   424	      if (app.stage === 5) {
425	   425	        const verdict = gateVerdict(out.gate ?? null)
426	   426	        if (verdict === 'fail') {
427	   427	          await ev.log('门禁 FAIL → 阶段 7 修复 (附证据)')
428	   428	          app = { ...app, status: 'pending', stage: 7 }
429	   429	        } else {
430	   430	          if (verdict === 'incomplete') await ev.log('门禁不完整 (有脚本未跑), 交给 QA 判断')
431	   431	          app = { ...app, status: 'pending', stage: 6 }
432	   432	        }
433	   433	      } else {
434	   434	        app = afterStage(app, out.qaVerdict)
435	   435	      }
436	   436	    } catch (err) {
437	   437	      const reason = `阶段 ${app.stage} 失败: ${String(err).slice(0, 300)}`
438	   438	      app = { ...app, status: 'blocked', note: reason, updatedAt: Date.now() }
439	   439	      await writeBlocked($, app, reason)
440	   440	      await ev.save(app)
441	   441	      ev.toast(`${app.app} 阶段 ${info.zh} 失败`)
442	   442	      await ev.log(reason)
443	   443	      return app
444	   444	    }
445	   445	    await ev.save(app)
446	   446	    if (app.status === 'waiting') ev.toast(`${app.app}: 阶段 ${info.zh} 完成 → 等待人工 (${app.waitingFor})`)
447	   447	    else if (app.status === 'blocked') {
448	   448	      await writeBlocked($, app, app.note ?? '')
449	   449	      ev.toast(`${app.app} 阻塞: ${app.note ?? ''}`)
450	   450	    } else if (app.status === 'done') ev.toast(`${app.app} 完成: showcase/ 已打包, /factory publish 发布`)
451	   451	    else ev.toast(`${app.app}: 阶段 ${info.zh} 完成`)
452	   452	  }
453	   453	  return app
454	   454	}
