576	    18	  for (let i = 0; i < raw.length; i++) {
577	    19	    const ch = raw[i] as string
578	    20	    if (quote) {
579	    21	      out += ch
580	    22	      if (ch === quote) quote = null
581	    23	      continue
582	    24	    }
