584	    26	      quote = ch
585	    27	      out += ch
586	    28	      continue
587	    29	    }
588	    30	    if (ch === '#' && (i === 0 || /\s/.test(raw[i - 1] as string))) break
589	    31	    out += ch
590	    32	  }
591	    33	  return out.replace(/\s+$/, '')
