598	    40	    return t.slice(1, -1).replace(/\\"/g, '"')
599	    41	  }
600	    42	  if (t === 'true') return true
601	    43	  if (t === 'false') return false
602	    44	  if (t === 'null' || t === '~') return null
603	    45	  if (/^[-+]?\d+$/.test(t)) return Number(t)
604	    46	  if (/^[-+]?\d*\.\d+$/.test(t)) return Number(t)
