644	    86	    else if (ch === '[' || ch === '{') depth++
645	    87	    else if (ch === ']' || ch === '}') depth--
646	    88	    else if (ch === ':' && depth === 0 && (i + 1 === text.length || /\s/.test(text[i + 1] as string))) {
