677	   119	const parseBlock = (lines: Line[], start: number, indent: number): [YamlValue, number] => {
678	   120	  const first = lines[start]
679	   121	  if (!first) return [null, start]
680	   122	  if (first.text.startsWith('- ') || first.text === '-') {
681	   123	    const list: YamlValue[] = []
682	   124	    let i = start
683	   125	    while (i < lines.length) {
684	   126	      const line = lines[i] as Line
685	   127	      if (line.indent !== indent || !(line.text.startsWith('- ') || line.text === '-')) break
686	   128	      const body = line.text === '-' ? '' : line.text.slice(2).trim()
687	   129	      if (body === '') {
688	   130	        const [v, next] = parseBlock(lines, i + 1, (lines[i + 1]?.indent ?? indent + 1))
689	   131	        list.push(v)
690	   132	        i = next
691	   133	      } else if (splitKey(body) && !body.startsWith('{') && !body.startsWith('[') && !body.startsWith('"')) {
692	   134	        // `- key: value` opens a mapping whose further keys are indented by two
693	   135	        const inner: Line[] = [{ indent: indent + 2, text: body, no: line.no }]
694	   136	        let j = i + 1
695	   137	        while (j < lines.length && (lines[j] as Line).indent > indent) {
696	   138	          inner.push(lines[j] as Line)
697	   139	          j++
698	   140	        }
699	   141	        const [v] = parseBlock(inner, 0, indent + 2)
700	   142	        list.push(v)
701	   143	        i = j
702	   144	      } else {
703	   145	        list.push(parseInline(body))
704	   146	        i++
705	   147	      }
706	   148	    }
707	   149	    return [list, i]
708	   150	  }
709	   151	  const map: YamlMap = {}
710	   152	  let i = start
711	   153	  while (i < lines.length) {
712	   154	    const line = lines[i] as Line
713	   155	    if (line.indent < indent) break
714	   156	    if (line.indent > indent) {
715	   157	      i++
716	   158	      continue
717	   159	    }
718	   160	    const kv = splitKey(line.text)
719	   161	    if (!kv) {
720	   162	      i++
721	   163	      continue
722	   164	    }
