724	   166	    if (rest === '') {
725	   167	      const next = lines[i + 1]
726	   168	      if (next && next.indent > indent) {
727	   169	        const [v, after] = parseBlock(lines, i + 1, next.indent)
728	   170	        map[key] = v
729	   171	        i = after
730	   172	      } else if (next && next.indent === indent && next.text.startsWith('- ')) {
731	   173	        const [v, after] = parseBlock(lines, i + 1, indent)
732	   174	        map[key] = v
