 * all showed the same early editing state. `present` lists the steps that have a frame, in walk order.
 */
export const montageSteps = (present: readonly string[], max = 6): string[] => {
  const unique = present.filter((s, i) => present.indexOf(s) === i)
  if (unique.length <= max) return unique
  const head = unique[0] === 'workbench' ? ['workbench'] : []
  const rest = unique.slice(head.length)
  const want = max - head.length
  const picked: string[] = []
  for (let i = 0; i < want; i++) {
    const at = Math.round((i * (rest.length - 1)) / Math.max(1, want - 1))
    const s = rest[at] as string
    if (!picked.includes(s)) picked.push(s)
  }
  return [...head, ...picked]
}

