(r"""// ---------------------------------------------------------------- runners

export type ScriptResult = { code: number | null; text: string }

/** Runs a child to its end through `$.process.spawn`, streaming each piece to `onText`. */
export async function runScript(
  $: EngineInterface,
  argv: readonly string[],
  cwd: string,
  onText?: (text: string) => void,
): Promise<ScriptResult> {
  const stream = $.process.spawn({ argv, cwd })
  let text = ''
  let step = await stream.next()
  while (!step.done) {
    text += step.value.text
    onText?.(step.value.text)
    step = await stream.next()
  }
  return { code: step.value.code, text }
}
""",
r"""// ---------------------------------------------------------------- host tools

/**
 * The hooks environment does not see the user's shell PATH (GridSpace dry run, 2026-10-17:
 * `$.process.spawn(['bash'])` → ENOENT, Git's bin folders are not on the engine's PATH), so every
 * executable is resolved to an absolute path once (`where.exe`, then known places) and every child
 * gets a PATH with those folders in front, so bash finds python/unzip/adb and python its user site.
 */
const WHERE_EXE = 'C:/Windows/System32/where.exe'
const CMD_EXE = 'C:/Windows/System32/cmd.exe'
const TOOL_CANDIDATES: Record<string, readonly string[]> = {
  bash: ['C:/Program Files/Git/usr/bin/bash.exe', 'C:/Program Files/Git/bin/bash.exe'],
  python: ['C:/Users/Admin/AppData/Local/Microsoft/WindowsApps/python.exe', 'C:/Python311/python.exe'],
  adb: ['C:/Users/Admin/AppData/Local/Android/Sdk/platform-tools/adb.exe'],
}
const toolCache = new Map<string, string>()
let hostEnvCache: Record<string, string> | null = null

/** The absolute path of a host tool, cached; the bare name when nothing finds it. */
export async function resolveTool($: EngineInterface, name: string): Promise<string> {
  const hit = toolCache.get(name)
  if (hit) return hit
  if (/[\\/]/.test(name)) return name
  let found: string | undefined
  try {
    const r = await $.process.run([WHERE_EXE, name], { timeoutMs: 10000 })
    if (r.exitCode === 0) found = r.stdout.split(/\r?\n/).map(s => s.trim()).find(s => /\.(exe|cmd|bat)$/i.test(s))
  } catch {
    /* where.exe itself missing: fall through to the candidates */
  }
  if (!found) {
    for (const c of TOOL_CANDIDATES[name] ?? []) {
      if (await exists($, c)) {
        found = c
        break
      }
    }
  }
  const path = (found ?? name).replace(/\\/g, '/')
  toolCache.set(name, path)
  return path
}

/** The child environment: the host's own variables (from `cmd /c set`) with the tools' folders leading PATH. */
export async function hostEnv($: EngineInterface): Promise<Record<string, string>> {
  if (hostEnvCache) return hostEnvCache
