    if (p.includes('/')) {
      const dir = p.slice(0, p.lastIndexOf('/')).replace(/\//g, '\\')
      if (!dirs.includes(dir)) dirs.push(dir)
    }
  }
  const pathKey = Object.keys(env).find(k => k.toUpperCase() === 'PATH') ?? 'PATH'
  const base = env[pathKey] ?? ''
  env[pathKey] = [...dirs, ...(base ? [base] : [])].join(';')
  env.PYTHONUTF8 = '1'
  hostEnvCache = env
  return env
}

/** `$.process.run` with argv[0] resolved and the host env. */
export async function hostRun($: EngineInterface, argv: readonly string[], init: { cwd?: string; timeoutMs?: number } = {}): Promise<{ exitCode: number; stdout: string; stderr: string }> {
  const [cmd = '', ...rest] = argv
  return $.process.run([await resolveTool($, cmd), ...rest], { ...init, env: await hostEnv($) })
}

// ---------------------------------------------------------------- runners

export type ScriptResult = { code: number | null; text: string }

/** Runs a child to its end through `$.process.spawn` (argv[0] resolved, host env), streaming each piece to `onText`. */
export async function runScript(
  $: EngineInterface,
  argv: readonly string[],
  cwd: string,
  onText?: (text: string) => void,
): Promise<ScriptResult> {
  const [cmd = '', ...rest] = argv
  const stream = $.process.spawn({ argv: [await resolveTool($, cmd), ...rest], cwd, env: await hostEnv($) })
  let text = ''
  let step = await stream.next()
  while (!step.done) {
    text += step.value.text
    onText?.(step.value.text)
    step = await stream.next()
  }
  return { code: step.value.code, text }
}
